input.command:
cd /tmp && wc -l out4.txt
echo "--- self-maps (uncountables / no-op rules) ---"
awk '{split($0,p," -> "); if (p[1]==p[2]) print}' out4.txt | sort
echo
echo "--- classify by which known rule explains it ---"
awk -F' -> ' '{
  t=$1; o=$2; n=length(t); base=substr(t,1,n-1);
  ok="UNEXPLAINED";
  # rule: (a)xes$ -> \1xis
  if (t ~ /axes$/ && o == substr(t,1,n-4) "axis") ok="AXES";
  else if (t ~ /ies$/ && substr(t,n-3,1) !~ /[aeiouy]/ && o == substr(t,1,n-3) "y") ok="IES";
  else if (t ~ /quies$/ && o == substr(t,1,n-5) "quy") ok="QUIES";
  else if (t ~ /ves$/ && substr(t,n-3,1) != "f" && o == substr(t,1,n-3) "fe") ok="VES";
  else if (t ~ /(xes|ches|sses|shes)$/ && o == substr(t,1,n-2)) ok="XCHSSSH";
  else if (t ~ /oes$/ && o == substr(t,1,n-2)) ok="OES";
  else if (t ~ /news$/ && o == t) ok="NEWS";
  else if (t ~ /(analy|ba|diagno|progno|synop|the|parenthe)ses$/) ok="SIS?";
  else if (t ~ /(cris|test)es$/) ok="CRISTEST";
  else if (t ~ /(alias|status)es$/) ok="ALIASSTATUS";
  else if (t ~ /(bus)es$/) ok="BUS";
  else if (t ~ /(vert|ind|matr)ices$/) ok="ICES";
  else if (t ~ /quizzes$/) ok="QUIZ";
  else if (o == t) ok="SELF/UNCOUNTABLE";
  print ok
}' out4.txt | sort | uniq -c | sort -rn
